import java.nio.ByteBuffer;

protected int findByte(byte value, int pos) {
    ByteBuffer buffer = ByteBuffer.allocate(1); // Allocate a buffer of size 1
    buffer.put(value); // Put the value into the buffer
    buffer.flip(); // Prepare the buffer for reading
    int index = 0;
    while (buffer.hasRemaining()) {
        if (buffer.get(index) == value) {
            return pos + index; // Return the position of the byte found
        }
        index++;
    }
    return -1; // Return -1 if the byte is not found
