import org.jgrapht.graph.DefaultGraphPath;

import java.util.Set;

protected <V, E> GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour.isEmpty()) {
        return null;
    }

    V startVertex = null;
    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        if (startVertex == null) {
            startVertex = source;
        }
        if (source.equals(target)) {
            throw new IllegalArgumentException("Self-loop detected: " + edge);
        }
        if (startVertex.equals(target)) {
            continue;
        }
        startVertex = target;
    }

    return new DefaultGraphPath<>(graph, startVertex, startVertex, tour.size());
}

