import java.util.ArrayList;
import java.util.List;

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSum = new ArrayList<>();
    long totalSum = 0;

    for (int i = bounds.size() - 1; i >= 0; i--) {
        int current = bounds.get(i);
        totalSum += current;
        if (i == bounds.size() - 1) {
            suffixSum.add(current);
        } else {
            suffixSum.add(current + suffixSum.get(suffixSum.size() - 1));
        }
    }

    List<Integer> result = new ArrayList<>();
    for (int i = suffixSum.size() - 1; i >= 0; i--) {
        result.add(suffixSum.get(i));
    }

    return Pair.with(result, totalSum);
}

