import java.util.ArrayDeque;
import java.util.Deque;

public class FrameStack {
    private Deque<Object> stack = new ArrayDeque<>();

    private void pop(final String descriptor) {
        int count = 0;
        for (char ch : descriptor.toCharArray()) {
            if (ch == ')') break;
            if (ch == 'J' || ch == 'D') {
                stack.pop(); // 64-bit
                stack.pop(); // 64-bit low parts
            } else if (ch == '[') {
                // Skip array type descriptor
                int i = descriptor.indexOf(';', stack.size() + 1);
                count += i - stack.size();
                stack = stack.subList(i + 1, stack.size());
                break;
            } else if (ch == 'L') {
                // Skip class type descriptor
                int i = descriptor.indexOf(';', stack.size() + 1);
                count += i - stack.size();
                stack = stack.subList(i + 1, stack.size());
            } else {
                count++;
            }
        }
        while (count > 0) {
            stack.pop();
            count--;
        }
    }
}

